# connected components of non-bg cells in test input
from collections import deque
H,W=len(a),len(a[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if a[r][c]!=6 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if 0<=p[0]<H and 0<=p[1]<W and p not in seen and a[p[0]][p[1]]!=6:
      seen.add(p);q.append(p)
   rs=[x for x,y in comp];cs=[y for x,y in comp];
   comps.append((len(comp),(min(rs),max(rs),min(cs),max(cs)),sorted({a[x][y] for x,y in comp})))
print(sorted(comps,key=lambda z:z[1]))
